"use client";
import { useRouter } from "next/navigation";
import { useEffect } from "react";

export default function SettingsCorePage() {
  const router = useRouter();

  useEffect(() => {
    router.replace("/settings/profile");
  }, []);

  return null;
}

import { apiClient, isUnauthorizedError } from "@/shared/api";
import { useQuery } from "@tanstack/react-query";
import { UserMe } from "../model/types";
import { authKeys } from "./auth.keys";

export const useMe = () => {
  return useQuery<UserMe | null>({
    queryKey: authKeys.me,
    queryFn: async () => {
      try {
        const res = await apiClient.get<UserMe>("/auth/me");
        return ((res as any)?.data ?? res) as UserMe;
      } catch (error) {
        if (isUnauthorizedError(error)) {
          return null;
        }
        throw error;
      }
    },
    retry: false,
    staleTime: 1000 * 60 * 5,
  });
};

import { apiClient } from "@/shared/api";
import { useQuery } from "@tanstack/react-query";
import { Session } from "../model/types";
import { sessionKeys } from "./session.keys";

export const useSessions = () => {
  return useQuery<Session[]>({
    queryKey: sessionKeys.list(),
    queryFn: async () => {
      const res = await apiClient.get<Session[]>("/auth/sessions");
      return ((res as any)?.data ?? res) as Session[];
    },
  });
};

