"use client";

import {
  PostContentInput,
  postContentSchema,
  useCreatePost,
} from "@/entities/post";
import { toastApiError } from "@/shared/lib/notify-api-error";
import { zodResolver } from "@hookform/resolvers/zod";
import { Eye, Paperclip, PaperPlane, TrashBin, Xmark } from "@gravity-ui/icons";
import { Button, Card, CardContent, Spinner, TextArea, toast } from "@heroui/react";
import Image from "next/image";
import React, { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";

interface CreatePostFormProps {
  crewId: number;
}

interface DraftFile {
  id: string;
  file: File;
  previewUrl?: string;
  type: "IMAGE" | "VIDEO" | "AUDIO" | "FILE";
}

export function CreatePostForm({ crewId }: CreatePostFormProps) {
  const { t } = useTranslation();
  const { mutate: createPost, isPending } = useCreatePost(crewId);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const [draftFiles, setDraftFiles] = useState<DraftFile[]>([]);
  const [previewMedia, setPreviewMedia] = useState<{
    url: string;
    type: "IMAGE" | "VIDEO";
    name: string;
  } | null>(null);

  const {
    register,
    handleSubmit,
    reset,
    watch,
    formState: { errors },
  } = useForm<PostContentInput>({
    resolver: zodResolver(postContentSchema),
    mode: "onChange",
    defaultValues: {
      content: "",
    },
  });

  const contentValue = watch("content") || "";
  const isTooLong = contentValue.length > 1500;

  useEffect(() => {
    const el = textareaRef.current;
    if (el) {
      el.style.height = "auto";
      const newHeight = Math.min(Math.max(el.scrollHeight, 84), 260);
      el.style.height = `${newHeight}px`;
    }
  }, [contentValue]);

  const { ref: registerRef, ...registerProps } = register("content");

  const handleFilesSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = Array.from(e.target.files || []);
    if (selectedFiles.length === 0) return;

    if (draftFiles.length + selectedFiles.length > 15) {
      toast.danger(t("api_errors.MAX_ATTACHMENTS_EXCEEDED"));
      return;
    }

    const newDrafts: DraftFile[] = [];
    for (const file of selectedFiles) {
      if (file.size > 200 * 1024 * 1024) {
        toast.danger(t("api_errors.ATTACHMENT_TOO_LARGE"));
        continue;
      }

      let type: "IMAGE" | "VIDEO" | "AUDIO" | "FILE" = "FILE";
      let previewUrl: string | undefined = undefined;

      if (file.type.startsWith("image/")) {
        type = "IMAGE";
        previewUrl = URL.createObjectURL(file);
      } else if (file.type.startsWith("video/")) {
        type = "VIDEO";
        previewUrl = URL.createObjectURL(file);
      } else if (file.type.startsWith("audio/")) {
        type = "AUDIO";
      }

      newDrafts.push({
        id: `${file.name}-${Date.now()}-${Math.random()}`,
        file,
        previewUrl,
        type,
      });
    }

    setDraftFiles((prev) => [...prev, ...newDrafts]);
    e.target.value = "";
  };

  const removeDraftFile = (id: string) => {
    setDraftFiles((prev) => {
      const item = prev.find((f) => f.id === id);
      if (item?.previewUrl) {
        URL.revokeObjectURL(item.previewUrl);
      }
      return prev.filter((f) => f.id !== id);
    });
  };

  const onSubmit = (data: PostContentInput) => {
    createPost(
      {
        content: data.content,
        files: draftFiles.map((df) => df.file),
      },
      {
        onSuccess: () => {
          toast.success(t("posts.create.success_toast"));
          reset();
          draftFiles.forEach((df) => {
            if (df.previewUrl) URL.revokeObjectURL(df.previewUrl);
          });
          setDraftFiles([]);
        },
        onError: (err) => {
          toastApiError(err);
        },
      },
    );
  };

  return (
    <Card className="border border-border/60 bg-surface/40 backdrop-blur-md rounded-3xl p-4 sm:p-5 shadow-xs transition-all hover:border-border/80">
      <CardContent className="p-0">
        <form onSubmit={handleSubmit(onSubmit)} className="flex flex-col gap-3">
          <div className="relative flex flex-col gap-1.5">
            <TextArea
              disabled={isPending}
              placeholder={t("posts.create.placeholder")}
              rows={3}
              className="w-full p-3.5 rounded-2xl bg-surface-secondary/50 border border-border/50 focus:border-accent/60 text-foreground text-sm resize-none outline-none focus:outline-none transition-all duration-150 max-h-64 overflow-y-auto"
              {...registerProps}
              ref={(e) => {
                registerRef(e);
                textareaRef.current = e as HTMLTextAreaElement | null;
              }}
            />
            <div className="flex items-center justify-between px-1 text-xs">
              <div>
                {errors.content?.message && (
                  <p className="text-danger font-medium animate-in fade-in-0 duration-150">
                    {t(errors.content.message)}
                  </p>
                )}
              </div>
              <span
                className={`font-mono text-[11px] ${
                  isTooLong
                    ? "text-danger font-bold"
                    : "text-foreground/40"
                }`}
              >
                {contentValue.length}/1500
              </span>
            </div>
          </div>

          {/* Draft Attachments Preview */}
          {draftFiles.length > 0 && (
            <div className="flex flex-wrap gap-2 p-2 rounded-2xl bg-surface-secondary/30 border border-border/40 max-h-48 overflow-y-auto">
              {draftFiles.map((df) => (
                <div
                  key={df.id}
                  className="relative group rounded-xl overflow-hidden border border-border/50 bg-background/80 flex items-center gap-2 p-1.5 pr-2 shrink-0"
                >
                  {df.type === "IMAGE" && df.previewUrl && (
                    <div className="relative w-10 h-10 rounded-lg overflow-hidden shrink-0">
                      <Image
                        src={df.previewUrl}
                        alt={df.file.name}
                        fill
                        unoptimized
                        className="object-cover"
                      />
                    </div>
                  )}

                  {df.type === "VIDEO" && (
                    <div className="w-10 h-10 rounded-lg bg-accent/20 text-accent flex items-center justify-center text-xs font-bold shrink-0">
                      VID
                    </div>
                  )}

                  {df.type === "AUDIO" && (
                    <div className="w-10 h-10 rounded-lg bg-accent/20 text-accent flex items-center justify-center text-xs font-bold shrink-0">
                      AUD
                    </div>
                  )}

                  {df.type === "FILE" && (
                    <div className="w-10 h-10 rounded-lg bg-accent/20 text-accent flex items-center justify-center text-xs font-bold shrink-0">
                      FILE
                    </div>
                  )}

                  <div className="flex flex-col min-w-0 max-w-[110px]">
                    <span className="text-xs font-medium text-foreground truncate">
                      {df.file.name}
                    </span>
                    <span className="text-[10px] text-foreground/50 font-mono">
                      {(df.file.size / (1024 * 1024)).toFixed(1)}MB
                    </span>
                  </div>

                  <div className="flex items-center gap-1 ml-1">
                    {(df.type === "IMAGE" || df.type === "VIDEO") && df.previewUrl && (
                      <Button
                        variant="outline"
                        size="sm"
                        isDisabled={isPending}
                        onPress={() =>
                          setPreviewMedia({
                            url: df.previewUrl!,
                            type: df.type as "IMAGE" | "VIDEO",
                            name: df.file.name,
                          })
                        }
                        className="w-6 h-6 min-w-0 p-0 rounded-full cursor-pointer bg-background/80 hover:bg-background text-foreground border-border/50"
                        aria-label="Preview"
                      >
                        <Eye className="w-3.5 h-3.5" />
                      </Button>
                    )}

                    <Button
                      variant="danger-soft"
                      size="sm"
                      isDisabled={isPending}
                      onPress={() => removeDraftFile(df.id)}
                      className="w-6 h-6 min-w-0 p-0 rounded-full cursor-pointer"
                      aria-label="Remove"
                    >
                      <Xmark className="w-3.5 h-3.5" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}

          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <input
                ref={fileInputRef}
                type="file"
                multiple
                disabled={isPending || draftFiles.length >= 15}
                onChange={handleFilesSelect}
                className="hidden"
              />
              <Button
                variant="outline"
                size="sm"
                isDisabled={isPending || draftFiles.length >= 15}
                onPress={() => fileInputRef.current?.click()}
                className="flex items-center gap-1.5 text-xs font-semibold cursor-pointer border-border/60 hover:bg-surface-secondary px-3 shrink-0"
              >
                <Paperclip className="w-4 h-4 text-foreground/70 shrink-0" />
                <span>{t("posts.attachments.add_btn")}</span>
                {draftFiles.length > 0 && (
                  <span className="text-foreground/60 font-normal ml-0.5">
                    ({draftFiles.length}/15)
                  </span>
                )}
              </Button>
            </div>

            <Button
              variant="primary"
              type="submit"
              isDisabled={!contentValue.trim() || isPending || isTooLong}
              className="flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-semibold cursor-pointer"
            >
              {isPending ? (
                <>
                  <Spinner size="sm" color="current" />
                  <span>{t("posts.create.submitting_btn")}</span>
                </>
              ) : (
                <>
                  <PaperPlane className="w-4 h-4" />
                  <span>{t("posts.create.submit_btn")}</span>
                </>
              )}
            </Button>
          </div>
        </form>
      </CardContent>

      {/* Lightbox Preview Modal for Draft Photos & Videos via Portal */}
      {typeof window !== "undefined" &&
        previewMedia &&
        createPortal(
          <div
            onClick={() => setPreviewMedia(null)}
            className="fixed inset-0 z-[99999] bg-black/60 backdrop-blur-md flex items-center justify-center p-4 sm:p-8 cursor-default animate-in fade-in-0 duration-200"
          >
            <Button
              variant="outline"
              size="sm"
              onPress={() => setPreviewMedia(null)}
              className="fixed top-5 right-5 z-[100000] w-11 h-11 min-w-0 p-0 rounded-full bg-white/10 hover:bg-white/20 text-white border-white/20 shadow-2xl cursor-pointer"
            >
              <Xmark className="w-6 h-6" />
            </Button>

            <div className="relative w-full h-full max-w-[95vw] max-h-[92vh] flex items-center justify-center cursor-default">
              {previewMedia.type === "IMAGE" ? (
                <Image
                  src={previewMedia.url}
                  alt={previewMedia.name}
                  fill
                  unoptimized
                  className="object-contain select-none"
                />
              ) : (
                <video
                  src={previewMedia.url}
                  controls
                  autoPlay
                  className="max-w-5xl max-h-[90vh] rounded-2xl object-contain shadow-2xl"
                />
              )}
            </div>
          </div>,
          document.body,
        )}
    </Card>
  );
}

"use client";

import { CrewMember, useCrewMembers } from "@/entities/crew";
import { useDebounce } from "@/shared/lib/use-debounce";
import { getAvatarUrl } from "@/shared/lib";
import {
  ArrowRight,
  Check,
  CheckDouble,
  Magnifier,
} from "@gravity-ui/icons";
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
  Button,
  Input,
  Spinner,
  TextArea,
} from "@heroui/react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

interface CreateSplitStep1Props {
  crewId: number;
  currentUserId?: number;
  title: string;
  onChangeTitle: (title: string) => void;
  desc: string;
  onChangeDesc: (desc: string) => void;
  selectedMemberIds: number[];
  onChangeSelectedMemberIds: (ids: number[]) => void;
  onGoToStep2: () => void;
  isPending?: boolean;
}

const getInitials = (name: string): string => {
  const parts = name.trim().split(/\s+/);
  if (parts.length === 0 || !parts[0]) return "U";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[1][0]).toUpperCase();
};

export function CreateSplitStep1({
  crewId,
  currentUserId,
  title,
  onChangeTitle,
  desc,
  onChangeDesc,
  selectedMemberIds,
  onChangeSelectedMemberIds,
  onGoToStep2,
  isPending = false,
}: CreateSplitStep1Props) {
  const { t } = useTranslation();
  const [searchQuery, setSearchQuery] = useState("");
  const debouncedSearchQuery = useDebounce(searchQuery, 300);

  const { data: membersData, isPending: isMembersPending } = useCrewMembers(
    crewId,
    { q: debouncedSearchQuery },
  );

  const allMembers = membersData?.items ?? [];

  const handleToggleMember = (userId: number) => {
    if (userId === currentUserId) return;

    if (selectedMemberIds.includes(userId)) {
      onChangeSelectedMemberIds(
        selectedMemberIds.filter((id) => id !== userId),
      );
    } else {
      onChangeSelectedMemberIds([...selectedMemberIds, userId]);
    }
  };

  const handleSelectAllMembers = () => {
    if (allMembers.length === 0) return;
    const allIds = allMembers.map((m) => m.userId);
    const nonSelfIds = allIds.filter((id) => id !== currentUserId);
    const areAllNonSelfSelected = nonSelfIds.every((id) =>
      selectedMemberIds.includes(id),
    );

    if (areAllNonSelfSelected) {
      onChangeSelectedMemberIds(currentUserId ? [currentUserId] : []);
    } else {
      const merged = Array.from(new Set([...selectedMemberIds, ...allIds]));
      onChangeSelectedMemberIds(merged);
    }
  };

  const isStep1Valid =
    title.trim().length >= 2 &&
    title.trim().length <= 30 &&
    selectedMemberIds.length >= 2;

  return (
    <div className="flex flex-col gap-6 animate-in fade-in-0 slide-in-from-left-4 duration-300">
      <div className="flex flex-col gap-4">
        <div className="flex flex-col gap-1.5">
          <label className="text-sm font-semibold text-foreground">
            {t("splits.wizard.title_label")}
          </label>
          <Input
            value={title}
            onChange={(e) => onChangeTitle(e.target.value)}
            placeholder={t("splits.wizard.title_placeholder")}
            disabled={isPending}
            className="w-full"
          />
        </div>

        <div className="flex flex-col gap-1.5">
          <div className="flex items-center justify-between">
            <label className="text-sm font-semibold text-foreground">
              {t("splits.wizard.desc_label")}
            </label>
            <span className="text-[11px] text-foreground/40 font-mono">
              {desc.length}/1500
            </span>
          </div>
          <TextArea
            value={desc}
            onChange={(e) => {
              if (e.target.value.length <= 1500) {
                onChangeDesc(e.target.value);
              }
            }}
            placeholder={t("splits.wizard.desc_placeholder")}
            rows={3}
            disabled={isPending}
            className="w-full p-3.5 rounded-2xl bg-surface-secondary/50 border border-border/50 focus:border-accent/60 text-foreground text-sm resize-none outline-none focus:outline-none transition-all duration-150 max-h-48 overflow-y-auto"
          />
        </div>
      </div>

      <div className="flex flex-col gap-3 pt-2">
        <div className="flex items-center justify-between flex-wrap gap-2">
          <h3 className="text-base font-bold text-foreground flex items-center gap-2">
            <span>{t("splits.wizard.select_members_title")}</span>
            <span className="px-2 py-0.5 rounded-full text-xs font-bold bg-accent/15 text-accent border border-accent/25">
              {selectedMemberIds.length}
            </span>
          </h3>

          <Button
            variant="outline"
            size="sm"
            onPress={handleSelectAllMembers}
            className="flex items-center gap-1.5 text-xs font-semibold cursor-pointer"
          >
            <CheckDouble className="w-4 h-4" />
            <span>
              {selectedMemberIds.length === allMembers.length
                ? t("splits.wizard.deselect_all")
                : t("splits.wizard.select_all")}
            </span>
          </Button>
        </div>

        <div className="relative">
          <Input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder={t("splits.wizard.search_members_placeholder")}
            className="w-full pl-9"
          />
          <Magnifier className="w-4 h-4 text-foreground/40 absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" />
        </div>

        {isMembersPending ? (
          <div className="flex justify-center py-8">
            <Spinner size="md" color="accent" />
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5 max-h-60 overflow-y-auto p-1">
            {allMembers.map((m) => {
              const isSelf = m.userId === currentUserId;
              const isSelected = selectedMemberIds.includes(m.userId);
              const displayName = m.alias || m.name;

              return (
                <div
                  key={m.id}
                  onClick={() => handleToggleMember(m.userId)}
                  className={`flex items-center justify-between p-3 rounded-2xl border transition-all select-none ${
                    isSelf
                      ? "bg-accent/20 border-accent text-foreground cursor-default"
                      : isSelected
                        ? "bg-accent/15 border-accent text-foreground cursor-pointer"
                        : "bg-surface/30 border-border/50 hover:bg-surface/60 text-foreground/70 cursor-pointer"
                  }`}
                >
                  <div className="flex items-center gap-3 min-w-0">
                    <Avatar size="sm" className="w-8 h-8 rounded-full shrink-0">
                      {m.avatar && (
                        <AvatarImage src={getAvatarUrl(m.avatar)} alt={displayName} />
                      )}
                      <AvatarFallback className="text-xs font-bold bg-accent/20 text-accent-foreground">
                        {getInitials(displayName)}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex flex-col min-w-0">
                      <div className="flex items-center gap-1.5">
                        <span className="text-xs font-bold truncate">
                          {displayName}
                        </span>
                        {isSelf && (
                          <span className="px-1.5 py-0.2 rounded-full text-[9px] font-bold bg-accent/20 text-accent">
                            {t("splits.wizard.you_badge")}
                          </span>
                        )}
                      </div>
                      {m.username && (
                        <span className="text-[10px] text-foreground/40 truncate">
                          @{m.username}
                        </span>
                      )}
                    </div>
                  </div>

                  {isSelected && (
                    <div className="w-5 h-5 rounded-full bg-accent text-accent-foreground flex items-center justify-center shrink-0">
                      <Check className="w-3.5 h-3.5" />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      <div className="flex justify-end pt-4 border-t border-border/40">
        <Button
          variant="primary"
          isDisabled={!isStep1Valid}
          onPress={onGoToStep2}
          className="flex items-center gap-2 px-6 py-2.5 rounded-xl font-semibold cursor-pointer"
        >
          <span>{t("splits.next_step_btn")}</span>
          <ArrowRight className="w-4 h-4" />
        </Button>
      </div>
    </div>
  );
}

"use client";

import { useMe } from "@/entities/auth";
import { CrewMember, useCrewMembers } from "@/entities/crew";
import { CreateSplitDto, CreateSplitExpenseDto, useCreateSplit } from "@/entities/split";
import { toastApiError } from "@/shared/lib/notify-api-error";
import { Card, CardContent, Chip, toast } from "@heroui/react";
import { useRouter } from "next/navigation";
import { useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { ExpenseDraft } from "../model/types";
import { CreateSplitStep1 } from "./CreateSplitStep1";
import { CreateSplitStep2 } from "./CreateSplitStep2";

interface CreateSplitWizardProps {
  crewId: number;
}

const round2 = (num: number): number =>
  Math.round((num + Number.EPSILON) * 100) / 100;

export function CreateSplitWizard({ crewId }: CreateSplitWizardProps) {
  const { t } = useTranslation();
  const router = useRouter();
  const { data: currentUser } = useMe();
  const currentUserId = currentUser?.id;

  const { mutate: createSplit, isPending } = useCreateSplit(crewId);

  const [step, setStep] = useState<1 | 2>(1);

  const [title, setTitle] = useState("");
  const [desc, setDesc] = useState("");

  const [selectedMemberIds, setSelectedMemberIds] = useState<number[]>(() =>
    currentUserId ? [currentUserId] : [],
  );

  const { data: membersData } = useCrewMembers(crewId);
  const allMembers = membersData?.items ?? [];

  const effectiveSelectedMemberIds = useMemo(() => {
    if (!currentUserId) return selectedMemberIds;
    if (selectedMemberIds.includes(currentUserId)) {
      return selectedMemberIds;
    }
    return [currentUserId, ...selectedMemberIds];
  }, [currentUserId, selectedMemberIds]);

  const selectedMembersMap = useMemo(() => {
    const map = new Map<number, CrewMember>();
    allMembers.forEach((m) => {
      if (effectiveSelectedMemberIds.includes(m.userId)) {
        map.set(m.userId, m);
      }
    });
    return map;
  }, [allMembers, effectiveSelectedMemberIds]);

  const [expenses, setExpenses] = useState<ExpenseDraft[]>(() => [
    {
      id: "1",
      title: "",
      desc: "",
      spenderId: 0,
      selectedUserIds: [],
      mode: "AUTO",
      totalAmount: "",
      manualShares: {},
    },
  ]);

  const handleGoToStep2 = () => {
    if (
      !title.trim() ||
      title.trim().length < 2 ||
      effectiveSelectedMemberIds.length < 2
    ) {
      return;
    }

    setExpenses((prevExpenses) =>
      prevExpenses.map((exp) => {
        const defaultSpender =
          exp.spenderId && effectiveSelectedMemberIds.includes(exp.spenderId)
            ? exp.spenderId
            : currentUserId && effectiveSelectedMemberIds.includes(currentUserId)
              ? currentUserId
              : effectiveSelectedMemberIds[0] || 0;
        return {
          ...exp,
          spenderId: defaultSpender,
          selectedUserIds: effectiveSelectedMemberIds,
        };
      }),
    );

    setStep(2);
  };

  const handleAddExpense = () => {
    if (expenses.length >= 10) return;
    const firstSpender = currentUserId || effectiveSelectedMemberIds[0] || 0;
    setExpenses((prev) => [
      ...prev,
      {
        id: String(Date.now()),
        title: "",
        desc: "",
        spenderId: firstSpender,
        selectedUserIds: [...effectiveSelectedMemberIds],
        mode: "AUTO",
        totalAmount: "",
        manualShares: {},
      },
    ]);
  };

  const handleRemoveExpense = (id: string) => {
    if (expenses.length <= 1) return;
    setExpenses((prev) => prev.filter((e) => e.id !== id));
  };

  const updateExpense = (id: string, updates: Partial<ExpenseDraft>) => {
    setExpenses((prev) =>
      prev.map((e) => (e.id === id ? { ...e, ...updates } : e)),
    );
  };

  const isStep2Valid = useMemo(() => {
    if (expenses.length === 0 || expenses.length > 10) return false;
    return expenses.every((exp) => {
      if (exp.title.trim().length < 2 || exp.title.trim().length > 30) {
        return false;
      }
      if (!exp.spenderId || !effectiveSelectedMemberIds.includes(exp.spenderId)) {
        return false;
      }
      if (exp.selectedUserIds.length < 2) {
        return false;
      }

      if (exp.mode === "AUTO") {
        const total = parseFloat(exp.totalAmount);
        return !isNaN(total) && total > 0;
      } else {
        return exp.selectedUserIds.every((userId) => {
          if (userId === exp.spenderId) return true;
          const share = parseFloat(exp.manualShares[userId] || "");
          return !isNaN(share) && share >= 0;
        });
      }
    });
  }, [expenses, effectiveSelectedMemberIds]);

  const handleSubmitFinal = () => {
    if (
      !title.trim() ||
      title.trim().length < 2 ||
      effectiveSelectedMemberIds.length < 2 ||
      !isStep2Valid
    ) {
      return;
    }

    const payloadExpenses: CreateSplitExpenseDto[] = expenses.map((exp) => {
      if (exp.mode === "AUTO") {
        const total = parseFloat(exp.totalAmount) || 0;
        const count = exp.selectedUserIds.length;
        const autoShare = count > 0 ? round2(total / count) : 0;

        const members = exp.selectedUserIds.map((userId) => {
          if (userId === exp.spenderId) {
            return {
              user: userId,
              paid: autoShare,
              mustPay: autoShare,
            };
          }
          return {
            user: userId,
            paid: 0,
            mustPay: autoShare,
          };
        });

        return {
          title: exp.title.trim(),
          desc: exp.desc.trim() || undefined,
          spender: exp.spenderId,
          members,
        };
      } else {
        let spenderPaidSum = 0;

        const members = exp.selectedUserIds.map((userId) => {
          if (userId === exp.spenderId) {
            return {
              user: userId,
              paid: 0,
              mustPay: 0,
            };
          }
          const share = parseFloat(exp.manualShares[userId] || "0") || 0;
          const roundedShare = round2(share);
          spenderPaidSum += roundedShare;
          return {
            user: userId,
            paid: 0,
            mustPay: roundedShare,
          };
        });

        const spenderShare = round2(
          spenderPaidSum / Math.max(1, exp.selectedUserIds.length),
        );
        const finalMembers = members.map((m) => {
          if (m.user === exp.spenderId) {
            return {
              user: m.user,
              paid: round2(spenderPaidSum),
              mustPay: spenderShare,
            };
          }
          return m;
        });

        return {
          title: exp.title.trim(),
          desc: exp.desc.trim() || undefined,
          spender: exp.spenderId,
          members: finalMembers,
        };
      }
    });

    const payload: CreateSplitDto = {
      title: title.trim(),
      desc: desc.trim() || undefined,
      expenses: payloadExpenses,
    };

    createSplit(payload, {
      onSuccess: () => {
        toast.success(t("splits.success_toast"));
        router.push(`/crews/${crewId}/splits`);
      },
      onError: (err) => {
        toastApiError(err);
      },
    });
  };

  return (
    <Card className="border border-border/60 bg-surface/40 backdrop-blur-md rounded-3xl p-6 sm:p-8 shadow-xs">
      <CardContent className="p-0 flex flex-col gap-6">
        <div className="flex items-center justify-between border-b border-border/40 pb-4">
          <div className="flex flex-col gap-1">
            <h2 className="text-xl font-bold text-foreground">
              {t("splits.wizard.title")}
            </h2>
            <p className="text-xs text-foreground/60">
              {step === 1
                ? t("splits.wizard.step1_desc")
                : t("splits.wizard.step2_desc")}
            </p>
          </div>
          <Chip size="sm" variant="soft" color="accent" className="font-bold">
            {t("splits.wizard.step_indicator", { current: step, total: 2 })}
          </Chip>
        </div>

        {step === 1 ? (
          <CreateSplitStep1
            crewId={crewId}
            currentUserId={currentUserId}
            title={title}
            onChangeTitle={setTitle}
            desc={desc}
            onChangeDesc={setDesc}
            selectedMemberIds={effectiveSelectedMemberIds}
            onChangeSelectedMemberIds={setSelectedMemberIds}
            onGoToStep2={handleGoToStep2}
            isPending={isPending}
          />
        ) : (
          <CreateSplitStep2
            expenses={expenses}
            selectedMemberIds={effectiveSelectedMemberIds}
            selectedMembersMap={selectedMembersMap}
            onBackToStep1={() => setStep(1)}
            onAddExpense={handleAddExpense}
            onRemoveExpense={handleRemoveExpense}
            onUpdateExpense={updateExpense}
            onSubmitFinal={handleSubmitFinal}
            isStep2Valid={isStep2Valid}
            isPending={isPending}
          />
        )}
      </CardContent>
    </Card>
  );
}

