"use client";

import { useIncreaseDebtExpenseMember } from "@/entities/split";
import { toastApiError } from "@/shared/lib/notify-api-error";
import { Plus } from "@gravity-ui/icons";
import {
  Button,
  Input,
  ModalBackdrop,
  ModalBody,
  ModalContainer,
  ModalDialog,
  ModalFooter,
  ModalHeader,
  ModalHeading,
  Spinner,
  toast,
} from "@heroui/react";
import { useEffect, useState } from "react";
