interface IncreaseDebtModalProps {
  splitId: number;
  expenseId: number;
  member: {
    userId: number;
    name: string;
  } | null;
  isOpen: boolean;
  onClose: () => void;
}

export function IncreaseDebtModal({
  splitId,
  expenseId,
  member,
  isOpen,
  onClose,
}: IncreaseDebtModalProps) {
  const { t } = useTranslation();
  const { mutate: increaseDebt, isPending } = useIncreaseDebtExpenseMember(
    splitId,
    expenseId,
  );

  const [amount, setAmount] = useState("");
  const [msg, setMsg] = useState("");

  useEffect(() => {
    if (member) {
      setAmount("");
      setMsg("");
    }
  }, [member]);

  const handleSubmit = () => {
    if (!member) return;
    const numAmount = parseFloat(amount);
    if (isNaN(numAmount) || numAmount <= 0) return;

    increaseDebt(
      [
        {
          user: member.userId,
          amount: numAmount,
          msg: msg.trim() || undefined,
        },
      ],
      {
        onSuccess: () => {
          toast.success(t("common.success"));
          onClose();
        },
        onError: (err) => {
          toastApiError(err);
        },
      },
    );
  };

  const parsedAmount = parseFloat(amount);
  const isValid =
    member &&
    !isNaN(parsedAmount) &&
    parsedAmount > 0 &&
    msg.length <= 50;

  return (
    <ModalBackdrop
      isOpen={isOpen}
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
      isDismissable
      isKeyboardDismissDisabled={false}
