                placeholder={t("splits.detail.amount_placeholder")}
                className="w-full"
              />
            </div>

            <div className="flex flex-col gap-1">
              <div className="flex items-center justify-between">
                <label className="text-xs font-semibold text-foreground">
                  {t("splits.detail.note_label")}
                </label>
                <span className="text-[10px] text-foreground/40 font-mono">
                  {msg.length}/50
                </span>
              </div>
              <Input
                value={msg}
                onChange={(e) => {
                  if (e.target.value.length <= 50) {
                    setMsg(e.target.value);
                  }
                }}
                placeholder={t("splits.detail.note_placeholder")}
                className="w-full"
              />
            </div>
          </ModalBody>

          <ModalFooter className="flex justify-end gap-3 pt-4">
            <Button
              variant="outline"
              type="button"
              isDisabled={isPending}
              onPress={onClose}
            >
              {t("common.cancel")}
            </Button>
            <Button
              variant="primary"
              type="button"
              isDisabled={isPending || !isValid}
              onPress={handleSubmit}
              className="flex items-center gap-2"
            >
              {isPending ? (
                <Spinner size="sm" color="current" />
              ) : (
                <Plus className="w-4 h-4" />
              )}
              <span>{t("splits.detail.submit_increase")}</span>
            </Button>
          </ModalFooter>
        </ModalDialog>
      </ModalContainer>
    </ModalBackdrop>
  );
}

