"use client";

import { SplitUser, useSplit } from "@/entities/split";
import { cn } from "@/shared/lib/utils";
import {
  SplitExpensesTab,
  SplitHeader,
  SplitHistoryTab,
  SplitRequestsTab,
} from "@/widgets/split-detail";
import { ArrowRotateRight, Clock, PaperPlane, Receipt, TriangleExclamationFill } from "@gravity-ui/icons";
import { Button, Card, CardContent, Spinner, Tab, TabList, Tabs } from "@heroui/react";
import { useParams } from "next/navigation";
import { useMemo, useState } from "react";
import { useTranslation } from "react-i18next";

export function SplitDetailView() {
  const { t } = useTranslation();
  const params = useParams();
  const crewId = Number(params?.id);
  const splitId = Number(params?.splitId);

  const [activeTab, setActiveTab] = useState<
    "expenses" | "history" | "requests"
  >("expenses");

  const { data: split, isPending, isError, refetch } = useSplit(splitId);

  const authors = useMemo(() => {
    if (!split) return [];
    const map = new Map<number, SplitUser>();
    split.expenses.forEach((e) => {
      if (e.spender) map.set(e.spender.id, e.spender);
      e.members?.forEach((m) => {
        if (m.user) map.set(m.user.id, m.user);
      });
    });
    return Array.from(map.values());
  }, [split]);

  const tabs = useMemo(() => {
    const list: Array<{
      id: "expenses" | "history" | "requests";
      label: string;
      icon: React.ReactNode;
      badge?: number;
    }> = [
      {
        id: "expenses",
        label: t("splits.tabs.expenses"),
        icon: <Receipt className="w-4 h-4" />,
      },
      {
        id: "history",
        label: t("splits.tabs.history"),
        icon: <Clock className="w-4 h-4" />,
      },
    ];

    if (!split?.archived) {
      list.push({
        id: "requests",
        label: t("splits.tabs.requests"),
        icon: <PaperPlane className="w-4 h-4" />,
        badge:
          split?.requestsCount && split.requestsCount > 0
            ? split.requestsCount
            : undefined,
      });
    }

    return list;
  }, [split?.archived, split?.requestsCount, t]);

  const currentTab = split?.archived && activeTab === "requests" ? "expenses" : activeTab;

  if (isPending) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-3">
        <Spinner size="lg" color="accent" />
      </div>
    );
  }

  if (isError || !split) {
    return (
      <Card className="border border-border/60 bg-surface/30 backdrop-blur-md rounded-3xl p-8 text-center">
        <CardContent className="flex flex-col items-center gap-4 p-0">
          <div className="w-12 h-12 rounded-2xl bg-danger/10 text-danger flex items-center justify-center border border-danger/20">
            <TriangleExclamationFill className="w-6 h-6" />
          </div>
          <div className="flex flex-col gap-1">
            <h3 className="text-base font-bold text-foreground">
              {t("common.error")}
            </h3>
          </div>
          <Button
            variant="outline"
            onPress={() => refetch()}
            className="flex items-center gap-2 mt-2"
          >
            <ArrowRotateRight className="w-4 h-4" />
            <span>{t("auth_guard.retry_btn")}</span>
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="flex flex-col gap-6 w-full animate-page-slide-in-right">
      <SplitHeader split={split} />

      <div className="w-full">
        <Tabs
          selectedKey={currentTab}
          onSelectionChange={(key) =>
            setActiveTab(key as "expenses" | "history" | "requests")
          }
          className="w-full"
        >
          <TabList
            className={`w-full grid gap-1 p-1.5 rounded-2xl bg-surface/50 border border-border/60 backdrop-blur-md shadow-xs ${
              split.archived ? "grid-cols-2" : "grid-cols-3"
            }`}
          >
            {tabs.map((tab) => {
              const isActive = currentTab === tab.id;

              return (
                <Tab
                  key={tab.id}
                  id={tab.id}
                  className={cn(
                    "flex items-center justify-center gap-2 py-2.5 px-3 rounded-xl text-xs font-semibold transition-colors duration-200 cursor-pointer select-none outline-none focus:outline-none",
                    isActive
                      ? "bg-accent text-accent-foreground font-bold shadow-xs"
                      : "text-foreground/70 hover:text-foreground hover:bg-surface-secondary/40",
                  )}
                >
                  {tab.icon}
                  <span>{tab.label}</span>
                  {typeof tab.badge === "number" && tab.badge > 0 && (
                    <span
                      className={cn(
                        "px-2 py-0.5 text-[10px] font-bold rounded-full transition-colors",
                        isActive
                          ? "bg-accent-foreground/20 text-accent-foreground"
                          : "bg-accent text-accent-foreground",
                      )}
                    >
                      {tab.badge}
                    </span>
                  )}
                </Tab>
              );
            })}
          </TabList>
        </Tabs>
      </div>

      {currentTab === "expenses" && (
        <SplitExpensesTab split={split} crewId={crewId} />
      )}
      {currentTab === "history" && (
        <SplitHistoryTab splitId={split.id} authors={authors} />
      )}
      {!split.archived && currentTab === "requests" && (
        <SplitRequestsTab splitId={split.id} authors={authors} />
      )}
    </div>
  );
}

"use client";

import { useMe } from "@/entities/auth";
import { getAvatarUrl } from "@/shared/lib";
import {
  SplitDetail,
  useDeleteExpense,
  useRemoveMembersFromExpense,
} from "@/entities/split";
import {
  AddMemberModal,
  CreateExpenseRequestModal,
  EditExpenseModal,
  IncreaseDebtModal,
  PayOffModal,
} from "@/features/manage-split-expense";
import { toastApiError } from "@/shared/lib/notify-api-error";
import { Check, PaperPlane, Pencil, PersonPlus, Plus, Receipt, TrashBin } from "@gravity-ui/icons";
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
  Button,
  Card,
  CardContent,
  Chip,
  ProgressBar,
  Tooltip,
  toast,
} from "@heroui/react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

interface SplitExpensesTabProps {
  split: SplitDetail;
  crewId: number;
}

interface PayOffTarget {
  expenseId: number;
  member: {
    userId: number;
    name: string;
    maxAmount: number;
  };
}

interface IncreaseTarget {
  expenseId: number;
  member: {
    userId: number;
    name: string;
  };
}

interface AddMemberTarget {
  expenseId: number;
  existingUserIds: number[];
}

interface CreateRequestTarget {
  expenseId: number;
  expenseTitle: string;
  maxAmount: number;
}

interface EditExpenseTarget {
  expenseId: number;
  title: string;
  desc?: string;
}

const getInitials = (name: string): string => {
  const parts = name.trim().split(/\s+/);
  if (parts.length === 0 || !parts[0]) return "U";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[1][0]).toUpperCase();
};

export function SplitExpensesTab({ split, crewId }: SplitExpensesTabProps) {
  const { t } = useTranslation();
  const { data: currentUser } = useMe();
  const currentUserId = currentUser?.id;

  const [payOffTarget, setPayOffTarget] = useState<PayOffTarget | null>(null);
  const [increaseTarget, setIncreaseTarget] = useState<IncreaseTarget | null>(null);
  const [addMemberTarget, setAddMemberTarget] = useState<AddMemberTarget | null>(null);
  const [createRequestTarget, setCreateRequestTarget] =
    useState<CreateRequestTarget | null>(null);
  const [editExpenseTarget, setEditExpenseTarget] =
    useState<EditExpenseTarget | null>(null);

  return (
    <div className="flex flex-col gap-6 w-full animate-in fade-in-0 duration-300">
      <div className="flex flex-col gap-6">
        {split.expenses.map((exp, index) => {
          const spenderName = exp.spender.alias || exp.spender.name;
          const isSpender = currentUserId === exp.spender.id;

          const currentUserMember = exp.members?.find(
            (m) => m.user.id === currentUserId,
          );
          const userRemainingDebt = currentUserMember
            ? Math.max(0, currentUserMember.mustPay - currentUserMember.paid)
            : 0;

          const expTotalPaid = exp.members?.reduce((acc, m) => acc + m.paid, 0) || 0;
          const expTotalMustPay =
            exp.members?.reduce((acc, m) => acc + m.mustPay, 0) || 0;

          const expProgressPercent =
            expTotalMustPay > 0
              ? Math.min(
                  100,
                  Math.round((expTotalPaid / expTotalMustPay) * 100),
                )
              : 0;

          return (
            <ExpenseCardItem
              key={exp.id}
              splitId={split.id}
              crewId={crewId}
              exp={exp}
              index={index}
              spenderName={spenderName}
              isSpender={isSpender}
              currentUserId={currentUserId}
              userRemainingDebt={userRemainingDebt}
              isSplitArchived={split.archived}
              expTotalPaid={expTotalPaid}
              expTotalMustPay={expTotalMustPay}
              expProgressPercent={expProgressPercent}
              onOpenPayOff={(target) => setPayOffTarget(target)}
              onOpenIncrease={(target) => setIncreaseTarget(target)}
              onOpenAddMember={() =>
                setAddMemberTarget({
                  expenseId: exp.id,
                  existingUserIds: exp.members.map((m) => m.user.id),
                })
              }
              onOpenCreateRequest={() =>
                setCreateRequestTarget({
                  expenseId: exp.id,
                  expenseTitle: exp.title,
                  maxAmount: userRemainingDebt,
                })
              }
              onOpenEditExpense={() =>
                setEditExpenseTarget({
                  expenseId: exp.id,
                  title: exp.title,
                  desc: exp.desc,
                })
              }
            />
          );
        })}
      </div>

      {payOffTarget && (
        <PayOffModal
          splitId={split.id}
          expenseId={payOffTarget.expenseId}
          member={payOffTarget.member}
          isOpen={Boolean(payOffTarget)}
          onClose={() => setPayOffTarget(null)}
        />
      )}

      {increaseTarget && (
        <IncreaseDebtModal
          splitId={split.id}
          expenseId={increaseTarget.expenseId}
          member={increaseTarget.member}
          isOpen={Boolean(increaseTarget)}
          onClose={() => setIncreaseTarget(null)}
        />
      )}

      {addMemberTarget && (
        <AddMemberModal
          splitId={split.id}
          expenseId={addMemberTarget.expenseId}
          crewId={crewId}
          existingUserIds={addMemberTarget.existingUserIds}
          isOpen={Boolean(addMemberTarget)}
          onClose={() => setAddMemberTarget(null)}
        />
      )}

      {createRequestTarget && (
        <CreateExpenseRequestModal
          splitId={split.id}
          expenseId={createRequestTarget.expenseId}
          expenseTitle={createRequestTarget.expenseTitle}
          maxAmount={createRequestTarget.maxAmount}
          isOpen={Boolean(createRequestTarget)}
          onClose={() => setCreateRequestTarget(null)}
        />
      )}

      {editExpenseTarget && (
        <EditExpenseModal
          splitId={split.id}
          expenseId={editExpenseTarget.expenseId}
          currentTitle={editExpenseTarget.title}
          currentDesc={editExpenseTarget.desc}
          isOpen={Boolean(editExpenseTarget)}
          onClose={() => setEditExpenseTarget(null)}
        />
      )}
    </div>
  );
}

interface ExpenseCardItemProps {
  splitId: number;
  crewId: number;
  exp: SplitDetail["expenses"][0];
  index: number;
  spenderName: string;
  isSpender: boolean;
  currentUserId?: number;
  userRemainingDebt: number;
  isSplitArchived: boolean;
  expTotalPaid: number;
  expTotalMustPay: number;
  expProgressPercent: number;
  onOpenPayOff: (target: PayOffTarget) => void;
  onOpenIncrease: (target: IncreaseTarget) => void;
  onOpenAddMember: () => void;
  onOpenCreateRequest: () => void;
  onOpenEditExpense: () => void;
}

function ExpenseCardItem({
  splitId,
  exp,
  index,
  spenderName,
  isSpender,
  currentUserId,
  isSplitArchived,
  expTotalPaid,
  expTotalMustPay,
  expProgressPercent,
  onOpenPayOff,
  onOpenIncrease,
  onOpenAddMember,
  onOpenCreateRequest,
  onOpenEditExpense,
}: ExpenseCardItemProps) {
  const { t } = useTranslation();
  const { mutate: removeMembers, isPending: isRemoving } =
    useRemoveMembersFromExpense(splitId, exp.id);
  const { mutate: deleteExpense, isPending: isDeleting } = useDeleteExpense(
    splitId,
    exp.id,
  );

  const handleRemoveUser = (userId: number) => {
    removeMembers(
      { userIds: [userId] },
      {
        onSuccess: () => {
          toast.success(t("common.success"));
        },
        onError: (err) => {
          toastApiError(err);
        },
      },
    );
  };

  const handleDeleteExpense = () => {
    deleteExpense(undefined, {
      onSuccess: () => {
        toast.success(t("common.success"));
      },
      onError: (err) => {
        toastApiError(err);
      },
    });
  };

  return (
    <Card className="border border-border/60 bg-surface/30 rounded-3xl p-5 sm:p-6 flex flex-col gap-5 shadow-xs">
      <CardContent className="p-0 flex flex-col gap-4">
        <div className="flex items-start justify-between gap-4 flex-wrap border-b border-border/30 pb-4">
          <div className="flex items-start gap-3 min-w-0">
            <div className="w-10 h-10 rounded-2xl bg-accent/15 text-accent border border-accent/25 flex items-center justify-center shrink-0 mt-0.5">
              <Receipt className="w-5 h-5" />
            </div>

            <div className="flex flex-col gap-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <h3 className="text-base font-bold text-foreground truncate">
                  {exp.title}
                </h3>
                <Chip
                  size="sm"
                  variant="soft"
                  color="accent"
                  className="text-[10px] font-bold"
                >
                  {t("splits.wizard.expense_num", { num: index + 1 })}
                </Chip>
              </div>

              {exp.desc && (
                <p className="text-xs text-foreground/60 leading-relaxed whitespace-pre-wrap">
                  {exp.desc}
                </p>
              )}

              <div className="flex items-center gap-1.5 mt-1 text-xs text-foreground/70">
                <span className="font-semibold">
                  {t("splits.detail.spender_label", {
                    name: spenderName,
                  })}
                </span>
                {exp.spender.username && (
                  <span className="text-foreground/40 font-mono">
                    (@{exp.spender.username})
                  </span>
                )}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3 shrink-0">
            {isSpender && !isSplitArchived && (
              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onPress={onOpenEditExpense}
                  className="flex items-center gap-1.5 text-xs font-semibold cursor-pointer"
                >
                  <Pencil className="w-4 h-4" />
                  <span>{t("splits.detail.edit_btn")}</span>
                </Button>

                <Button
                  variant="outline"
                  size="sm"
                  onPress={onOpenAddMember}
                  className="flex items-center gap-1.5 text-xs font-semibold cursor-pointer"
                >
                  <PersonPlus className="w-4 h-4" />
                  <span>{t("splits.detail.add_members_btn")}</span>
                </Button>

                <Button
                  variant="danger"
                  size="sm"
                  isDisabled={isDeleting}
                  onPress={handleDeleteExpense}
                  className="p-1.5 rounded-xl h-8 w-8 min-w-0 cursor-pointer"
                >
                  <TrashBin className="w-4 h-4" />
                </Button>
              </div>
            )}

            <div className="flex flex-col items-end gap-1">
              <span className="text-sm font-bold font-mono text-foreground">
                {t("splits.detail.paid_of", {
                  paid: expTotalPaid,
                  total: expTotalMustPay,
                })}
              </span>
              <span className="text-xs text-foreground/50 font-medium">
                {expProgressPercent}%
              </span>
            </div>
          </div>
        </div>

        <ProgressBar value={expProgressPercent} aria-label={exp.title}>
          <ProgressBar.Track className="h-2 w-full rounded-full bg-surface-secondary/70 overflow-hidden relative">
            <ProgressBar.Fill
              className="h-full bg-accent rounded-full transition-all duration-500"
              style={{ width: `${expProgressPercent}%` }}
            />
          </ProgressBar.Track>
        </ProgressBar>

        <div className="flex flex-col gap-2.5 pt-2">
          <span className="text-xs font-semibold text-foreground/70">
            {t("splits.wizard.expense_participants")} ({exp.members.length})
          </span>

          <div className="flex flex-col gap-2">
            {exp.members.map((m, mIndex) => {
              const memberName = m.user.alias || m.user.name;
              const isExpenseSpenderMember = m.user.id === exp.spender.id;
              const isMe = m.user.id === currentUserId;
              const remainingDebt = Math.max(0, m.mustPay - m.paid);
              const isSettled = remainingDebt === 0;

              return (
                <div
                  key={m.user.id || mIndex}
                  className="flex items-center justify-between p-3 rounded-2xl border border-border/40 bg-surface-secondary/40 text-xs transition-colors"
                >
                  <div className="flex items-center gap-3 min-w-0">
                    <Avatar size="sm" className="w-8 h-8 rounded-full shrink-0">
                      {m.user.avatar && (
                        <AvatarImage src={getAvatarUrl(m.user.avatar)} alt={memberName} />
                      )}
                      <AvatarFallback className="text-xs font-bold bg-accent/20 text-accent-foreground">
                        {getInitials(memberName)}
                      </AvatarFallback>
                    </Avatar>

                    <div className="flex flex-col min-w-0">
                      <div className="flex items-center gap-1.5">
                        <span className="font-bold truncate">{memberName}</span>
                        {isExpenseSpenderMember && (
                          <Chip
                            size="sm"
                            variant="soft"
                            color="accent"
                            className="text-[9px] font-bold px-1.5 py-0"
                          >
                            {t("splits.wizard.spender_badge")}
                          </Chip>
                        )}
                        {isMe && !isExpenseSpenderMember && (
                          <Chip
                            size="sm"
                            variant="soft"
                            color="accent"
                            className="text-[9px] font-bold px-1.5 py-0"
                          >
                            {t("splits.wizard.you_badge")}
                          </Chip>
                        )}
                      </div>
                      {m.user.username && (
                        <span className="text-[10px] text-foreground/40 font-mono truncate">
                          @{m.user.username}
                        </span>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center gap-3 shrink-0">
                    {isMe && !isSpender && !isSplitArchived && !isSettled && (
                      <Button
                        variant="outline"
                        size="sm"
                        onPress={onOpenCreateRequest}
                        className="flex items-center gap-1.5 text-[11px] font-semibold text-accent border-accent/40 hover:bg-accent/10 cursor-pointer py-1 px-2.5 h-7"
                      >
                        <PaperPlane className="w-3.5 h-3.5" />
                        <span>{t("splits.detail.create_request_btn")}</span>
                      </Button>
                    )}

                    <div className="flex flex-col items-end gap-0.5">
                      <span className="font-mono font-bold text-foreground">
                        {m.paid} / {m.mustPay} ₴
                      </span>
                      {isSettled ? (
                        <span className="text-[10px] font-bold text-success flex items-center gap-0.5">
                          <Check className="w-3 h-3" />
                          <span>{t("splits.detail.settled_badge")}</span>
                        </span>
                      ) : (
                        <span className="text-[10px] font-bold text-danger">
                          {t("splits.detail.owes_label", {
                            amount: remainingDebt,
                          })}
                        </span>
                      )}
                    </div>

                    {isSpender && !isSplitArchived && !isExpenseSpenderMember && (
                      <div className="flex items-center gap-1.5">
                        {!isSettled && (
                          <Tooltip key="pay-off">
                            <Tooltip.Trigger>
                              <Button
                                variant="outline"
                                size="sm"
                                onPress={() =>
                                  onOpenPayOff({
                                    expenseId: exp.id,
                                    member: {
                                      userId: m.user.id,
                                      name: memberName,
                                      maxAmount: remainingDebt,
                                    },
                                  })
                                }
                                className="p-1.5 rounded-xl h-8 w-8 min-w-0 text-success border-success/30 hover:bg-success/10 cursor-pointer"
                              >
                                <Check className="w-4 h-4" />
                              </Button>
                            </Tooltip.Trigger>
                            <Tooltip.Content className="px-2 py-1 text-[11px] rounded-md bg-background border border-border shadow-md">
                              {t("splits.detail.pay_off_btn")}
                            </Tooltip.Content>
                          </Tooltip>
                        )}

                        <Tooltip key="increase">
                          <Tooltip.Trigger>
                            <Button
                              variant="outline"
                              size="sm"
                              onPress={() =>
                                onOpenIncrease({
                                  expenseId: exp.id,
                                  member: {
                                    userId: m.user.id,
                                    name: memberName,
                                  },
                                })
                              }
                              className="p-1.5 rounded-xl h-8 w-8 min-w-0 text-accent border-accent/30 hover:bg-accent/10 cursor-pointer"
                            >
                              <Plus className="w-4 h-4" />
                            </Button>
                          </Tooltip.Trigger>
                          <Tooltip.Content className="px-2 py-1 text-[11px] rounded-md bg-background border border-border shadow-md">
                            {t("splits.detail.increase_btn")}
                          </Tooltip.Content>
                        </Tooltip>

                        {exp.members.length > 2 && (
                          <Tooltip key="remove">
                            <Tooltip.Trigger>
                              <Button
                                variant="danger"
                                size="sm"
                                isDisabled={isRemoving}
                                onPress={() => handleRemoveUser(m.user.id)}
                                className="p-1.5 rounded-xl h-8 w-8 min-w-0 cursor-pointer"
                              >
                                <TrashBin className="w-4 h-4" />
                              </Button>
                            </Tooltip.Trigger>
                            <Tooltip.Content className="px-2 py-1 text-[11px] rounded-md bg-background border border-border shadow-md">
                              {t("splits.detail.remove_member_btn")}
                            </Tooltip.Content>
                          </Tooltip>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useSplitHistory } from "@/entities/split";
import { formatRelativeTime } from "@/shared/lib/format-relative-time";
import { getAvatarUrl } from "@/shared/lib";
import { useDebounce } from "@/shared/lib/use-debounce";
import { Clock, Comment, Magnifier, Receipt, TriangleExclamationFill } from "@gravity-ui/icons";
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
  Card,
  CardContent,
  Chip,
  Input,
  Spinner,
} from "@heroui/react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

interface SplitHistoryTabProps {
  splitId: number;
  authors: Array<{
    id: number;
    name: string;
    alias?: string | null;
    avatar?: string | null;
    username?: string | null;
  }>;
}

const getInitials = (name: string): string => {
  const parts = name.trim().split(/\s+/);
  if (parts.length === 0 || !parts[0]) return "U";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[1][0]).toUpperCase();
};

export function SplitHistoryTab({ splitId, authors }: SplitHistoryTabProps) {
  const { t } = useTranslation();

  const [searchQuery, setSearchQuery] = useState("");
  const debouncedQuery = useDebounce(searchQuery, 300);

  const [selectedUserId, setSelectedUserId] = useState<string>("");

  const { data, isPending, isError } = useSplitHistory(splitId, {
    q: debouncedQuery || undefined,
    userId: selectedUserId ? Number(selectedUserId) : undefined,
  });

  const historyItems = data?.items ?? [];

  return (
    <div className="flex flex-col gap-6 w-full animate-in fade-in-0 duration-300">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-4 rounded-3xl border border-border/60 bg-surface/30 backdrop-blur-md">
        <div className="relative">
          <Input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder={t("splits.detail.search_history_placeholder")}
            className="w-full pl-9"
          />
          <Magnifier className="w-4 h-4 text-foreground/40 absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" />
        </div>

        <select
          value={selectedUserId}
          onChange={(e) => setSelectedUserId(e.target.value)}
          className="w-full p-2.5 rounded-xl bg-surface-secondary/50 border border-border/50 text-foreground text-xs font-semibold outline-none cursor-pointer"
        >
          <option value="">{t("splits.detail.all_members")}</option>
          {authors.map((author) => (
            <option key={author.id} value={author.id}>
              {author.alias || author.name}
            </option>
          ))}
        </select>
      </div>

      {isPending ? (
        <div className="flex justify-center py-12">
          <Spinner size="lg" color="accent" />
        </div>
      ) : isError ? (
        <Card className="border border-border/60 bg-surface/30 p-6 text-center">
          <CardContent className="flex flex-col items-center gap-2 p-0">
            <TriangleExclamationFill className="w-6 h-6 text-danger" />
            <span className="text-sm font-semibold text-foreground">
              {t("common.error")}
            </span>
          </CardContent>
        </Card>
      ) : historyItems.length === 0 ? (
        <Card className="border border-border/60 bg-surface/30 p-10 text-center">
          <CardContent className="flex flex-col items-center gap-3 p-0 max-w-sm mx-auto">
            <Receipt className="w-8 h-8 text-foreground/40" />
            <span className="text-sm font-semibold text-foreground/70">
              {t("splits.detail.empty_history")}
            </span>
          </CardContent>
        </Card>
      ) : (
        <div className="flex flex-col gap-3">
          {historyItems.map((item) => {
            const userName = item.user.alias || item.user.name;
            const isPayOff = item.type === "PAY";

            return (
              <Card
                key={item.id}
                className="border border-border/50 bg-surface/40 p-4 rounded-2xl flex flex-col gap-3 hover:bg-surface/60 transition-colors shadow-xs"
              >
                <CardContent className="p-0 flex flex-col gap-3">
                  <div className="flex items-center justify-between gap-3 flex-wrap">
                    <div className="flex items-center gap-3 min-w-0">
                      <Avatar
                        size="sm"
                        className="w-9 h-9 rounded-full shrink-0"
                      >
                        {item.user.avatar && (
                          <AvatarImage
                            src={getAvatarUrl(item.user.avatar)}
                            alt={userName}
                          />
                        )}
                        <AvatarFallback className="text-[10px] font-bold bg-accent/20 text-accent-foreground">
                          {getInitials(userName)}
                        </AvatarFallback>
                      </Avatar>

                      <div className="flex flex-col min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="text-xs font-bold text-foreground">
                            {userName}
                          </span>

                          <Chip
                            size="sm"
                            variant="soft"
                            color={isPayOff ? "success" : "accent"}
                            className="text-[9px] font-bold px-1.5 py-0"
                          >
                            {isPayOff
                              ? t("splits.detail.history_pay_off_badge")
                              : t("splits.detail.history_increase_badge")}
                          </Chip>

                          {item.procByRequest && (
                            <Chip
                              size="sm"
                              variant="soft"
                              color="accent"
                              className="text-[9px] font-bold px-1.5 py-0"
                            >
                              {t("splits.detail.proc_by_request")}
                            </Chip>
                          )}

                          <span className="text-xs font-mono font-bold text-foreground">
                            {item.amount} ₴
                          </span>
                        </div>

                        <span className="text-[11px] text-foreground/60 font-medium">
                          {isPayOff
                            ? t("splits.detail.history_pay_off", {
                                amount: item.amount,
                                name: userName,
                              })
                            : t("splits.detail.history_increase", {
                                amount: item.amount,
                                name: userName,
                              })}
                        </span>
                      </div>
                    </div>

                    <div className="flex items-center gap-1.5 text-[11px] text-foreground/40 font-medium shrink-0">
                      <Clock className="w-3.5 h-3.5" />
                      <span>{formatRelativeTime(item.createdAt)}</span>
                    </div>
                  </div>

                  {item.msg && (
                    <div className="flex flex-col gap-1 p-3 rounded-xl bg-surface-secondary/50 border border-border/40 text-xs text-foreground/80">
                      <div className="flex items-center gap-2">
                        <Comment className="w-3.5 h-3.5 text-accent shrink-0" />
                        {item.procByRequest && (
                          <span className="text-[10px] text-foreground/50 font-medium italic">
                            ({t("splits.detail.proc_by_request")})
                          </span>
                        )}
                      </div>
                      <p className="italic font-medium leading-relaxed pl-5">
                        "{item.msg}"
                      </p>
                    </div>
                  )}
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { useMe } from "@/entities/auth";
import { getAvatarUrl } from "@/shared/lib";
import {
  ExpenseRequestItem,
  ExpenseRequestRoleFilter,
  useAcceptExpenseRequest,
  useCancelExpenseRequest,
  useDeclineExpenseRequest,
  useExpenseRequests,
} from "@/entities/split";
import { formatRelativeTime } from "@/shared/lib/format-relative-time";
import { toastApiError } from "@/shared/lib/notify-api-error";
import { Check, Clock, Comment, PaperPlane, TriangleExclamationFill, Xmark } from "@gravity-ui/icons";
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
  Button,
  Card,
  CardContent,
  Chip,
  Spinner,
  toast,
} from "@heroui/react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

interface SplitRequestsTabProps {
  splitId: number;
  authors: Array<{
    id: number;
    name: string;
    alias?: string | null;
    avatar?: string | null;
    username?: string | null;
  }>;
}

const getInitials = (name: string): string => {
  const parts = name.trim().split(/\s+/);
  if (parts.length === 0 || !parts[0]) return "U";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[1][0]).toUpperCase();
};

export function SplitRequestsTab({ splitId, authors }: SplitRequestsTabProps) {
  const { t } = useTranslation();
  const { data: currentUser } = useMe();
  const currentUserId = currentUser?.id;

  const [roleFilter, setRoleFilter] =
    useState<ExpenseRequestRoleFilter>("all");
  const [selectedUserId, setSelectedUserId] = useState<string>("");

  const { data, isPending, isError } = useExpenseRequests(splitId, {
    role: roleFilter,
    userId: selectedUserId ? Number(selectedUserId) : undefined,
  });

  const requests = data?.items ?? [];

  return (
    <div className="flex flex-col gap-6 w-full animate-in fade-in-0 duration-300">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-4 rounded-3xl border border-border/60 bg-surface/30 backdrop-blur-md">
        <select
          value={roleFilter}
          onChange={(e) =>
            setRoleFilter(e.target.value as ExpenseRequestRoleFilter)
          }
          className="w-full p-2.5 rounded-xl bg-surface-secondary/50 border border-border/50 text-foreground text-xs font-semibold outline-none cursor-pointer"
        >
          <option value="all">{t("splits.detail.filter_role_all")}</option>
          <option value="as_spender">
            {t("splits.detail.filter_role_as_spender")}
          </option>
          <option value="as_user">
            {t("splits.detail.filter_role_as_user")}
          </option>
        </select>

        <select
          value={selectedUserId}
          onChange={(e) => setSelectedUserId(e.target.value)}
          className="w-full p-2.5 rounded-xl bg-surface-secondary/50 border border-border/50 text-foreground text-xs font-semibold outline-none cursor-pointer"
        >
          <option value="">{t("splits.detail.all_members")}</option>
          {authors.map((author) => (
            <option key={author.id} value={author.id}>
              {author.alias || author.name}
            </option>
          ))}
        </select>
      </div>

      {isPending ? (
        <div className="flex justify-center py-12">
          <Spinner size="lg" color="accent" />
        </div>
      ) : isError ? (
        <Card className="border border-border/60 bg-surface/30 p-6 text-center">
          <CardContent className="flex flex-col items-center gap-2 p-0">
            <TriangleExclamationFill className="w-6 h-6 text-danger" />
            <span className="text-sm font-semibold text-foreground">
              {t("common.error")}
            </span>
          </CardContent>
        </Card>
      ) : requests.length === 0 ? (
        <Card className="border border-border/60 bg-surface/30 p-10 text-center">
          <CardContent className="flex flex-col items-center gap-3 p-0 max-w-sm mx-auto">
            <PaperPlane className="w-8 h-8 text-foreground/40" />
            <span className="text-sm font-semibold text-foreground/70">
              {t("splits.detail.empty_requests")}
            </span>
          </CardContent>
        </Card>
      ) : (
        <div className="flex flex-col gap-4">
          {requests.map((item) => (
            <RequestCardItem
              key={item.id}
              splitId={splitId}
              item={item}
              currentUserId={currentUserId}
            />
          ))}
        </div>
      )}
    </div>
  );
}

interface RequestCardItemProps {
  splitId: number;
  item: ExpenseRequestItem;
  currentUserId?: number;
}

function RequestCardItem({
  splitId,
  item,
  currentUserId,
}: RequestCardItemProps) {
  const { t } = useTranslation();

  const isMyRequest = currentUserId === item.user.id;
  const isSpender = currentUserId === item.expense.spender.id;

  const userName = item.user.alias || item.user.name;
  const spenderName =
    item.expense.spender.alias || item.expense.spender.name;

  const { mutate: cancelRequest, isPending: isCanceling } =
    useCancelExpenseRequest(splitId, item.expense.id);
  const { mutate: acceptRequest, isPending: isAccepting } =
    useAcceptExpenseRequest(splitId, item.expense.id);
  const { mutate: declineRequest, isPending: isDeclining } =
    useDeclineExpenseRequest(splitId, item.expense.id);

  const handleCancel = () => {
    cancelRequest(item.id, {
      onSuccess: () => toast.success(t("common.success")),
      onError: (err) => toastApiError(err),
    });
  };

  const handleAccept = () => {
    acceptRequest(item.id, {
      onSuccess: () => toast.success(t("common.success")),
      onError: (err) => toastApiError(err),
    });
  };

  const handleDecline = () => {
    declineRequest(item.id, {
      onSuccess: () => toast.success(t("common.success")),
      onError: (err) => toastApiError(err),
    });
  };

  return (
    <Card className="border border-border/60 bg-surface/40 p-5 rounded-3xl flex flex-col gap-4 shadow-xs">
      <CardContent className="p-0 flex flex-col gap-4">
        <div className="flex items-start justify-between gap-4 flex-wrap border-b border-border/30 pb-3">
          <div className="flex items-center gap-3 min-w-0">
            <Avatar size="sm" className="w-10 h-10 rounded-full shrink-0">
              {item.user.avatar && (
                <AvatarImage src={getAvatarUrl(item.user.avatar)} alt={userName} />
              )}
              <AvatarFallback className="text-xs font-bold bg-accent/20 text-accent-foreground">
                {getInitials(userName)}
              </AvatarFallback>
            </Avatar>

            <div className="flex flex-col min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className="text-sm font-bold text-foreground truncate">
                  {userName}
                </span>

                {isMyRequest && (
                  <Chip
                    size="sm"
                    variant="soft"
                    color="accent"
                    className="text-[9px] font-bold px-1.5 py-0"
                  >
                    {t("splits.wizard.you_badge")}
                  </Chip>
                )}
              </div>

              <span className="text-xs text-foreground/70 leading-normal">
                {isMyRequest
                  ? t("splits.detail.you_claim_text", {
                      amount: item.amount,
                      title: item.expense.title,
                      spender: spenderName,
                    })
                  : t("splits.detail.request_claim_text", {
                      user: userName,
                      amount: item.amount,
                      title: item.expense.title,
                      spender: spenderName,
                    })}
              </span>
            </div>
          </div>

          <div className="flex items-center gap-2 shrink-0">
            <span className="text-base font-mono font-bold text-foreground">
              {item.amount} ₴
            </span>
          </div>
        </div>

        {item.msg && (
          <div className="flex items-start gap-2.5 p-3 rounded-2xl bg-surface-secondary/50 border border-border/40 text-xs text-foreground/80">
            <Comment className="w-4 h-4 text-accent shrink-0 mt-0.5" />
            <p className="italic font-medium leading-relaxed">"{item.msg}"</p>
          </div>
        )}

        <div className="flex items-center justify-between gap-4 flex-wrap pt-1">
          <div className="flex items-center gap-1.5 text-xs text-foreground/40 font-medium">
            <Clock className="w-3.5 h-3.5" />
            <span>{formatRelativeTime(item.createdAt)}</span>
          </div>

          <div className="flex items-center gap-2">
            {isMyRequest && (
              <Button
                variant="danger"
                size="sm"
                isDisabled={isCanceling}
                onPress={handleCancel}
                className="flex items-center gap-1.5 text-xs font-semibold cursor-pointer"
              >
                {isCanceling ? (
                  <Spinner size="sm" color="current" />
                ) : (
                  <Xmark className="w-4 h-4" />
                )}
                <span>{t("splits.detail.cancel_request_btn")}</span>
              </Button>
            )}

            {isSpender && (
              <>
                <Button
                  variant="outline"
                  size="sm"
                  isDisabled={isDeclining || isAccepting}
                  onPress={handleDecline}
                  className="flex items-center gap-1.5 text-xs font-semibold text-danger border-danger/30 hover:bg-danger/10 cursor-pointer"
                >
                  {isDeclining ? (
                    <Spinner size="sm" color="current" />
                  ) : (
                    <Xmark className="w-4 h-4" />
                  )}
                  <span>{t("splits.detail.decline_request_btn")}</span>
                </Button>

                <Button
                  variant="primary"
                  size="sm"
                  isDisabled={isAccepting || isDeclining}
                  onPress={handleAccept}
                  className="flex items-center gap-1.5 text-xs font-semibold cursor-pointer"
                >
                  {isAccepting ? (
                    <Spinner size="sm" color="current" />
                  ) : (
                    <Check className="w-4 h-4" />
                  )}
                  <span>{t("splits.detail.accept_request_btn")}</span>
                </Button>
              </>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}
